import * as cssParser from "css";
import { Jss } from "jss";
import { ThemeTokens } from "../theming";
import createGenerateId from "./createGenerateId";
import isolateStyles from "./isolateStyles";
import { StyleFn } from "../elements";

type Modes = "light" | "dark";

/**
 * Generates a CSS stylesheet for a given HTML element or a set of related elements from its/theirs style function(s).
 * It supports a theme's color modes by prefixing impacted rules' selectors with [data-theme='<mode>']
 */
export const generateStylesheet = (
  elementName: string,
  styleFn: StyleFn,
  theme: ThemeTokens,
  jss: Jss
) => {
  console.log(`Generating stylesheet for "${elementName}"`);
  const css = (jssObj: any, prefix = "") => {
    const sheet = jss.createStyleSheet(isolateStyles(jssObj, theme), {
      generateId: createGenerateId(elementName, prefix),
    });
    return sheet.toString();
  };
  let defaultJSS, defaultCSS;
  try {
    defaultJSS = styleFn(theme, "light");
  } catch (err) {
    console.error(`"FATAL: JSS styleFn failed\n`, err);
  }
  try {
    defaultCSS = css(defaultJSS);
  } catch (err) {
    console.error(`"FATAL: css generation failed\n`, err);
  }

  const variants = [defaultCSS];
  const altModes: Modes[] = ["dark"];
  for (const mode of altModes) {
    // For each alternative color mode we generate an alternate CSS
    const altJSS = styleFn(theme, mode);
    const altCSS = css(altJSS);

    // If the color mode impacts the element's styles, we get a different stylesheet (obviously).
    // But we're only interested by the CSS declarations that really change, thus we want to compare
    // the 2 stylesheets and extract the differences. This is done by comparing ASTs.
    if (altCSS !== defaultCSS) {
      const defaultAST = cssParser.parse(defaultCSS as string);
      const altAST = cssParser.parse(altCSS);
      const rules: any[] = [];
      if (
        !defaultAST.stylesheet ||
        !altAST.stylesheet ||
        defaultAST.stylesheet.rules.length !== altAST.stylesheet.rules.length
      ) {
        console.error(
          "FATAL: a stylesheet should return the same number of rules on all modes"
        );
        return;
      }
      altAST.stylesheet.rules.forEach((rule: any, i) => {
        // The code below is basically to please Typescript...
        if (rule.type !== "rule") return;
        if (!defaultAST.stylesheet) return;
        const defaultRule = defaultAST.stylesheet.rules[i];
        if (!defaultRule) return;
        const defaultDeclarations = (defaultRule as cssParser.Rule)
          .declarations;
        if (!defaultDeclarations) return;
        const declarationsDiff: any[] = [];
        // For each declaration (ex: color: #fff) of a rule (ex: ds-button { color: #fff; })
        // in the alternate CSS, we check if it's present in the default one or if the value
        // is different. In either case, we need to include that declaration in our alternate rule
        // (ex: [data-theme="dark"] ds-button { color: #000; })
        rule.declarations.forEach((decl: any) => {
          const defaultDecl = defaultDeclarations.find(
            (d: any) => d.property === decl.property
          );
          if (
            !defaultDecl ||
            decl.value != (defaultDecl as cssParser.Declaration).value
          ) {
            declarationsDiff.push({
              type: "declaration",
              property: decl.property,
              value: decl.value,
            });
          }
        });
        // Here we add the alternate rule to our rules array, and prefix its selector
        if (declarationsDiff.length !== 0) {
          rules.push({
            type: "rule",
            selectors: [
              `[data-theme='${mode}'] ${rule.selectors[0]}, [data-theme='${mode}']${rule.selectors[0]}`,
            ],
            declarations: declarationsDiff,
          });
        }
      });
      // At the end, we only have rules/declarations that change with the color mode,
      // and we generate the CSS.
      if (rules.length !== 0) {
        const diffAST = {
          type: "stylesheet",
          stylesheet: { source: undefined, rules },
        };
        variants.push(cssParser.stringify(diffAST));
      }
    }
  }
  return variants.join("\n");
};

export default generateStylesheet;
